#[doc = r"Results returned by `calc_ptf_wosten2001_hydraulic`."]
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Wosten2001HydraulicResult {
    #[doc = r"Volumetric water content at the supplied pressure-head magnitude. (cm³/cm³)"]
    pub water_content: f64,
    #[doc = r"Hydraulic conductivity at the supplied pressure-head magnitude. (cm/day)"]
    pub conductivity: f64,
}
#[doc = r"Evaluate water content and conductivity from Staring Series parameters.

# Arguments

  * theta_r: Residual volumetric water content. (cm³/cm³)
  * theta_s: Saturated volumetric water content. (cm³/cm³)
  * saturated_conductivity: Saturated hydraulic conductivity. (cm/day)
  * alpha: van Genuchten inverse pressure-head scale. (1/cm)
  * conductivity_shape_parameter: Mualem hydraulic-conductivity shape parameter. (dimensionless)
  * n: van Genuchten pore-size distribution parameter. (dimensionless)
  * pressure_head_magnitude: Nonnegative magnitude of pressure head; callers must convert any
    signed-negative convention explicitly before calling. (cm)

# Returns

A [`Wosten2001HydraulicResult`].

# Models

  * h(theta): van Genuchten model with m = 1 - 1 / n
  * k(h): Mualem-van Genuchten hydraulic-conductivity model

# Notes

Prediction target: Volumetric water content and unsaturated hydraulic conductivity at a
nonnegative pressure-head magnitude.
Pressure head is accepted as a nonnegative magnitude to make the sign convention explicit.

# Warnings

Parameters must belong to one internally consistent van Genuchten-Mualem parameter set."]
#[cfg_attr(feature = "inline", inline)]
#[must_use]
pub fn calc_ptf_wosten2001_hydraulic(
    theta_r: f64,
    theta_s: f64,
    saturated_conductivity: f64,
    alpha: f64,
    conductivity_shape_parameter: f64,
    n: f64,
    pressure_head_magnitude: f64,
) -> Wosten2001HydraulicResult {
    let m = 1.0f64 - 1.0f64 / n;
    let pressure_term = (alpha * pressure_head_magnitude).powf(n);
    let effective_saturation = (1.0f64 + pressure_term).powf(-m);
    let water_content = theta_r + (theta_s - theta_r) * effective_saturation;
    let conductivity = saturated_conductivity
        * effective_saturation.powf(conductivity_shape_parameter)
        * (1.0f64 - (1.0f64 - effective_saturation.powf(1.0f64 / m)).powf(m)).powi(2);
    Wosten2001HydraulicResult {
        water_content,
        conductivity,
    }
}
