#[doc = r"Evaluate the printed Table 5 regressions for mineral loam and clay soils.

# Arguments

  * clay: Mass percentage of particles smaller than 2 micrometers. (%)
  * organic_matter: Soil organic-matter mass percentage. (%)

# Returns

A [`Wosten2001Table5Parameters`].

# Models

  * h(theta): Table 5 parameter regressions for the van Genuchten model
  * k(h): Table 5 parameter regressions for the Mualem-van Genuchten model

# Notes

Prediction target: Bulk density, saturated water content, saturated conductivity, and the alpha,
l, and n parameters from the printed loam-and-clay regressions.
Positive clay and organic-matter inputs are required by reciprocal and natural-log terms.

# Warnings

The reciprocal-density expression must be positive before inversion.
These are the printed rounded Table 5 equations; they do not claim numerical parity with the
unavailable Staringreeks 1.0 program.
The report does not publish the legacy program's applicability-warning thresholds."]
#[cfg_attr(feature = "inline", inline)]
#[must_use]
pub fn calc_ptf_wosten2001_loam_clay_table5(
    clay: f64,
    organic_matter: f64,
) -> Wosten2001Table5Parameters {
    let organic_matter_squared = organic_matter.powi(2);
    let reciprocal_organic_matter = 1.0f64 / organic_matter;
    let ln_clay = clay.ln();
    let ln_organic_matter = organic_matter.ln();
    let reciprocal_density = 0.6117f64
        + 0.003601f64 * clay
        + 0.002172f64 * organic_matter_squared
        + 0.01715f64 * ln_organic_matter;
    let bulk_density = 1.0f64 / reciprocal_density;
    let bulk_density_squared = bulk_density.powi(2);
    let density_organic_matter = bulk_density * organic_matter;
    let density_clay = bulk_density * clay;
    let clay_organic_matter = clay * organic_matter;
    let theta_s = 0.6311f64 + 0.003383f64 * clay
        - 0.09699f64 * bulk_density_squared
        - 0.00204f64 * density_clay;
    let log_saturated_conductivity = -42.6f64 + 8.71f64 * organic_matter + 61.9f64 * bulk_density
        - 20.79f64 * bulk_density_squared
        - 0.2107f64 * organic_matter_squared
        - 0.01622f64 * clay_organic_matter
        - 5.382f64 * density_organic_matter;
    let saturated_conductivity = log_saturated_conductivity.exp();
    let log_alpha = -19.13f64 + 0.812f64 * organic_matter + 23.4f64 * bulk_density
        - 8.16f64 * bulk_density_squared
        + 0.423f64 * reciprocal_organic_matter
        + 2.388f64 * ln_organic_matter
        - 1.338f64 * density_organic_matter;
    let alpha = log_alpha.exp();
    let transformed_l = 0.102f64 + 0.0222f64 * clay - 0.043f64 * density_clay;
    let exp_transformed_l = transformed_l.exp();
    let conductivity_shape_parameter =
        10.0f64 * (exp_transformed_l - 1.0f64) / (exp_transformed_l + 1.0f64);
    let log_n_minus_one = -0.235f64 + 0.972f64 * reciprocal_density
        - 0.7743f64 * ln_clay
        - 0.3154f64 * ln_organic_matter
        + 0.0678f64 * density_organic_matter;
    let n = 1.0f64 + log_n_minus_one.exp();
    Wosten2001Table5Parameters {
        bulk_density,
        theta_s,
        saturated_conductivity,
        alpha,
        conductivity_shape_parameter,
        n,
    }
}
